import { DateTime } from "luxon";
import { q, one, type Db } from "../db";
import { notFound } from "../errors";
import { dayStart, minutesToLabel } from "../time";

// ----------------------------------------------------------------------------
// Types
// ----------------------------------------------------------------------------
export type Business = {
  id: string; slug: string; name: string; type: string; timezone: string; description: string;
  address: string; phone: string; contact_email: string; has_logo: boolean;
  online_booking_enabled: boolean; ai_enabled: boolean;
};
export type Policies = {
  slot_interval_min: number; default_duration_min: number; buffer_min: number; max_party_size: number;
  min_notice_min: number; max_advance_days: number; early_checkin_min: number; late_grace_min: number;
  cancel_cutoff_min: number; reminder_hours_before: number; email_notifications: boolean;
  cancellation_policy: string; late_policy: string; arrival_instructions: string;
};
export type Service = {
  id: string; name: string; description: string; duration_min: number | null; price_cents: number | null;
  currency: string; resource_type: string; active: boolean;
};
export type Resource = { id: string; type: string; name: string; capacity: number; active: boolean };
export type Hours = { weekday: number; open_min: number; close_min: number };
export type Closure = { id: string; starts_at: Date; ends_at: Date; reason: string };

export type BookingContext = {
  business: Business; policies: Policies; services: Service[]; resources: Resource[]; hours: Hours[]; closures: Closure[];
};

export const BUSINESS_COLUMNS =
  "b.id, b.slug, b.name, b.type, b.timezone, b.description, b.address, b.phone, b.contact_email, (b.logo IS NOT NULL) AS has_logo, b.online_booking_enabled, b.ai_enabled";

/** Everything the engine needs to reason about one business. Always scoped by business id. */
export async function loadContext(businessId: string, db?: Db): Promise<BookingContext> {
  const business = await one<Business>(`SELECT ${BUSINESS_COLUMNS} FROM businesses b WHERE b.id = $1`, [businessId], db);
  if (!business) throw notFound("Business not found");
  // Sequential on purpose: `db` may be a single transaction connection, which runs one query at a time.
  const policies = await one<Policies>("SELECT * FROM business_policies WHERE business_id = $1", [businessId], db);
  const services = await q<Service>("SELECT id, name, description, duration_min, price_cents, currency, resource_type, active FROM services WHERE business_id = $1 ORDER BY sort, name", [businessId], db);
  const resources = await q<Resource>("SELECT id, type, name, capacity, active FROM resources WHERE business_id = $1 ORDER BY capacity, sort, name", [businessId], db);
  const hours = await q<Hours>("SELECT weekday, open_min, close_min FROM opening_hours WHERE business_id = $1 ORDER BY weekday, open_min", [businessId], db);
  const closures = await q<Closure>("SELECT id, starts_at, ends_at, reason FROM closures WHERE business_id = $1 AND ends_at > now() - interval '1 day' ORDER BY starts_at", [businessId], db);
  return { business, policies: policies!, services, resources, hours, closures };
}

export function pickService(ctx: BookingContext, serviceId?: string | null): Service | null {
  const active = ctx.services.filter((s) => s.active);
  if (serviceId) return active.find((s) => s.id === serviceId) ?? null;
  return active[0] ?? null;
}

export const durationOf = (ctx: BookingContext, s: Service) => s.duration_min ?? ctx.policies.default_duration_min;

// ----------------------------------------------------------------------------
// Occupancy
// ----------------------------------------------------------------------------
type Busy = { resource_id: string; starts_at: Date; blocked_until: Date; id: string };

/** Live reservations that could collide with anything between `from` and `to`. */
export async function loadBusy(businessId: string, from: Date, to: Date, db?: Db): Promise<Busy[]> {
  return q<Busy>(
    `SELECT id, resource_id, starts_at, blocked_until FROM reservations
      WHERE business_id = $1 AND status IN ('pending','confirmed','checked_in')
        AND starts_at < $3 AND blocked_until > $2`,
    [businessId, from, to],
    db,
  );
}

// ----------------------------------------------------------------------------
// Slot checking
// ----------------------------------------------------------------------------
export type SlotReason =
  | "ok" | "closed" | "outside_hours" | "off_grid" | "closure" | "too_soon" | "too_far" | "past"
  | "party_too_large" | "no_capacity" | "full";

export type SlotCheck = { ok: boolean; reason: SlotReason; start: Date; end: Date; blockedUntil: Date; candidates: Resource[] };

export type CheckOptions = {
  now?: Date;
  /** Staff may book outside the customer rules (notice, advance limit, grid, party limit). */
  staff?: boolean;
  /** Ignore this reservation's own occupancy (used when rescheduling). */
  excludeReservationId?: string;
};

/**
 * Decide whether a booking of `partySize` for `service` can start at `start`.
 * Returns the free resources that fit, smallest first — or the reason it cannot be booked.
 * This is the single source of truth: the slot list, the AI tools and reservation creation all call it.
 */
export function checkSlot(ctx: BookingContext, service: Service, start: Date, partySize: number, busy: Busy[], opts: CheckOptions = {}): SlotCheck {
  const { policies: p, business } = ctx;
  const now = opts.now ?? new Date();
  const duration = durationOf(ctx, service);
  const end = new Date(start.getTime() + duration * 60_000);
  const blockedUntil = new Date(end.getTime() + p.buffer_min * 60_000);
  const fail = (reason: SlotReason): SlotCheck => ({ ok: false, reason, start, end, blockedUntil, candidates: [] });

  const local = DateTime.fromJSDate(start, { zone: business.timezone });
  const startMin = local.hour * 60 + local.minute;
  const endMin = startMin + duration;

  if (start.getTime() <= now.getTime()) return fail("past");
  if (!opts.staff) {
    if (start.getTime() < now.getTime() + p.min_notice_min * 60_000) return fail("too_soon");
    const lastDay = DateTime.fromJSDate(now, { zone: business.timezone }).startOf("day").plus({ days: p.max_advance_days + 1 });
    if (local >= lastDay) return fail("too_far");
    if (partySize > p.max_party_size) return fail("party_too_large");
  }

  const todays = ctx.hours.filter((h) => h.weekday === local.weekday);
  if (todays.length === 0) return fail("closed");
  const window = todays.find((h) => startMin >= h.open_min && endMin <= h.close_min);
  if (!window) return fail("outside_hours");
  if (!opts.staff && (startMin - window.open_min) % p.slot_interval_min !== 0) return fail("off_grid");

  if (ctx.closures.some((c) => c.starts_at < end && c.ends_at > start)) return fail("closure");

  const fitting = ctx.resources.filter((r) => r.active && r.type === service.resource_type && r.capacity >= partySize);
  if (fitting.length === 0) return fail("no_capacity");

  const candidates = fitting.filter(
    (r) => !busy.some((b) => b.resource_id === r.id && b.id !== opts.excludeReservationId && b.starts_at < blockedUntil && b.blocked_until > start),
  );
  if (candidates.length === 0) return fail("full");
  // Smallest fitting resource first, so a party of 2 does not take the only table for 6.
  candidates.sort((a, b) => a.capacity - b.capacity);
  return { ok: true, reason: "ok", start, end, blockedUntil, candidates };
}

export type Slot = { start: string; time: string; available: boolean; reason: SlotReason; free: number };
export type DayAvailability = { date: string; open: boolean; closedReason: string | null; slots: Slot[] };

type DayArgs = { date: string; partySize: number; serviceId?: string | null } & CheckOptions;

/** All grid slots for one business-local day, each marked available or not. */
export async function getDayAvailability(businessId: string, args: DayArgs, db?: Db, preloaded?: BookingContext): Promise<DayAvailability> {
  const ctx = preloaded ?? (await loadContext(businessId, db));
  const service = pickService(ctx, args.serviceId);
  if (!service) return { date: args.date, open: false, closedReason: "No bookable service is configured.", slots: [] };

  const day = dayStart(args.date, ctx.business.timezone);
  if (!day.isValid) return { date: args.date, open: false, closedReason: "Invalid date.", slots: [] };
  const todays = ctx.hours.filter((h) => h.weekday === day.weekday);
  if (todays.length === 0) return { date: args.date, open: false, closedReason: "Closed on this day.", slots: [] };

  const dayEnd = day.plus({ days: 1 });
  const fullClosure = ctx.closures.find((c) => c.starts_at <= day.toJSDate() && c.ends_at >= dayEnd.toJSDate());
  if (fullClosure) return { date: args.date, open: false, closedReason: fullClosure.reason || "Closed on this day.", slots: [] };

  const busy = await loadBusy(businessId, day.minus({ days: 1 }).toJSDate(), dayEnd.plus({ days: 1 }).toJSDate(), db);
  const duration = durationOf(ctx, service);
  const slots: Slot[] = [];
  for (const h of todays) {
    for (let m = h.open_min; m + duration <= h.close_min; m += ctx.policies.slot_interval_min) {
      // Build the instant from local wall-clock time so daylight-saving changes are handled by the zone.
      const start = day.set({ hour: Math.floor(m / 60), minute: m % 60 });
      if (start.hour * 60 + start.minute !== m) continue; // wall-clock time skipped by a DST jump
      const c = checkSlot(ctx, service, start.toJSDate(), args.partySize, busy, args);
      slots.push({ start: start.toUTC().toISO()!, time: minutesToLabel(m), available: c.ok, reason: c.reason, free: c.candidates.length });
    }
  }
  return { date: args.date, open: true, closedReason: null, slots };
}

export type Alternative = { date: string; time: string; start: string };

/**
 * Real alternatives when a requested time cannot be booked: the closest free times on the same
 * day first, then the first free times on following days. Never returns a slot that is not free.
 */
export async function findAlternatives(
  businessId: string,
  args: { date: string; time?: string | null; partySize: number; serviceId?: string | null; limit?: number; days?: number } & CheckOptions,
  db?: Db,
): Promise<Alternative[]> {
  const ctx = await loadContext(businessId, db);
  const limit = args.limit ?? 4;
  const out: Alternative[] = [];
  const wanted = args.time ? toMin(args.time) : null;
  const first = dayStart(args.date, ctx.business.timezone);
  if (!first.isValid) return out;
  for (let i = 0; i <= (args.days ?? 14) && out.length < limit; i++) {
    const date = first.plus({ days: i }).toISODate()!;
    const day = await getDayAvailability(businessId, { ...args, date }, db, ctx);
    let free = day.slots.filter((s) => s.available);
    if (wanted !== null) free = [...free].sort((a, b) => Math.abs(toMin(a.time) - wanted) - Math.abs(toMin(b.time) - wanted));
    for (const s of free.slice(0, limit - out.length)) out.push({ date, time: s.time, start: s.start });
  }
  return out;
}

const toMin = (t: string) => Number(t.slice(0, 2)) * 60 + Number(t.slice(3, 5));

export function reasonText(reason: SlotReason, ctx: BookingContext): string {
  switch (reason) {
    case "closed": return "We are closed that day.";
    case "outside_hours": return "That time is outside our opening hours.";
    case "off_grid": return `Bookings start every ${ctx.policies.slot_interval_min} minutes.`;
    case "closure": return "We are closed at that time.";
    case "too_soon": return "That time is too soon to book online.";
    case "too_far": return `Bookings open up to ${ctx.policies.max_advance_days} days ahead.`;
    case "past": return "That time has already passed.";
    case "party_too_large": return `Online bookings are limited to ${ctx.policies.max_party_size} guests. Please contact us for larger groups.`;
    case "no_capacity": return "We cannot seat a group of that size.";
    case "full": return "That time is fully booked.";
    default: return "";
  }
}
