import { env } from "../env";
import type { LocalContext } from "./local";

export type ToolCall = { id: string; name: string; arguments: Record<string, unknown> };
export type ChatMessage =
  | { role: "user"; content: string }
  | { role: "assistant"; content: string; toolCalls?: ToolCall[] }
  | { role: "tool"; toolCallId: string; name: string; content: string };

export type ToolDef = { name: string; description: string; parameters: Record<string, unknown> };
export type ChatRequest = { system: string; messages: ChatMessage[]; tools: ToolDef[]; context: LocalContext };
export type ChatResponse = { text: string; toolCalls: ToolCall[]; usage?: { in: number; out: number } };

/** Any model backend. The rest of the app never talks to a model API directly. */
export interface AiProvider {
  name: string;
  chat(req: ChatRequest): Promise<ChatResponse>;
}

export class AiUnavailable extends Error {}

let override: AiProvider | null = null;
export function setAiProviderForTests(p: AiProvider | null) { override = p; }

export async function aiProvider(): Promise<AiProvider> {
  if (override) return override;
  if (env.aiProvider === "openai" && env.aiBaseUrl && env.aiApiKey && env.aiModel) {
    return (await import("./openai")).openAiCompatible();
  }
  return (await import("./local")).localAssistant;
}

/** What the UI tells staff about the assistant that is actually running. */
export function aiProviderInfo(): { kind: "llm" | "basic"; label: string } {
  if (env.aiProvider === "openai" && env.aiBaseUrl && env.aiApiKey && env.aiModel) {
    return { kind: "llm", label: `${env.aiModel} via ${new URL(env.aiBaseUrl).host}` };
  }
  return { kind: "basic", label: "Built-in basic assistant (no AI model connected)" };
}
