import { one, q } from "../db";
import { AppError } from "../errors";
import { randomToken, sha256 } from "../crypto";
import { log } from "../audit";
import { env } from "../env";
import { rateLimit } from "../ratelimit";
import { publish } from "../realtime";
import { loadContext, type Business } from "../booking/availability";
import { getAgent, getFaqs } from "../business";
import { aiProvider, type ChatMessage, type ToolCall } from "./provider";
import { buildLocalContext, buildSystemPrompt } from "./prompt";
import { executeTool, TOOL_DEFS, type ToolContext, type ToolOutcome } from "./tools";

const MAX_TOOL_ROUNDS = 6;
const MAX_TURNS = 40;
const HISTORY = 60;

export type ChatReply = {
  token: string;
  reply: string;
  ticket?: ToolOutcome["ticket"];
  escalated: boolean;
  /** true when the assistant could not answer (paused, provider down); the page should point to the form. */
  degraded: boolean;
};

type Conversation = { id: string; turn: number; status: string; pending_action: ToolContext["conversation"]["pending_action"]; reservation_id: string | null };

/** External channels (WhatsApp): one running conversation per customer number, restarted after a day of silence. */
async function loadExternalConversation(businessId: string, channel: string, externalId: string): Promise<{ conv: Conversation; token: string }> {
  const conv = await one<Conversation>(
    `SELECT id, turn, status, pending_action, reservation_id FROM conversations
      WHERE business_id = $1 AND channel = $2 AND external_id = $3 AND status <> 'closed' AND updated_at > now() - interval '24 hours'
      ORDER BY updated_at DESC LIMIT 1`, [businessId, channel, externalId]);
  if (conv) return { conv, token: "" };
  const fresh = (await one<Conversation>(
    "INSERT INTO conversations (business_id, channel, external_id, token_hash) VALUES ($1,$2,$3,$4) RETURNING id, turn, status, pending_action, reservation_id",
    [businessId, channel, externalId, sha256(randomToken(24))]))!;
  return { conv: fresh, token: "" };
}

async function loadConversation(businessId: string, token: string | null): Promise<{ conv: Conversation; token: string }> {
  if (token && token.length <= 100) {
    const conv = await one<Conversation>(
      "SELECT id, turn, status, pending_action, reservation_id FROM conversations WHERE token_hash = $1 AND business_id = $2", [sha256(token), businessId]);
    if (conv) return { conv, token };
  }
  const fresh = randomToken(24);
  const conv = (await one<Conversation>(
    "INSERT INTO conversations (business_id, token_hash) VALUES ($1,$2) RETURNING id, turn, status, pending_action, reservation_id", [businessId, sha256(fresh)]))!;
  return { conv, token: fresh };
}

async function save(conversationId: string, role: string, content: string, toolName: string | null = null, payload: unknown = null) {
  await q("INSERT INTO messages (conversation_id, role, content, tool_name, payload) VALUES ($1,$2,$3,$4,$5)",
    [conversationId, role, content, toolName, payload ? JSON.stringify(payload) : null]);
}

async function history(conversationId: string): Promise<ChatMessage[]> {
  const rows = (await q<{ role: string; content: string; tool_name: string | null; payload: { toolCalls?: ToolCall[]; toolCallId?: string } | null }>(
    "SELECT role, content, tool_name, payload FROM (SELECT * FROM messages WHERE conversation_id = $1 AND role <> 'system' ORDER BY id DESC LIMIT $2) m ORDER BY id",
    [conversationId, HISTORY]));
  // Never start mid-exchange: a tool result must follow the assistant message that requested it.
  while (rows.length && rows[0].role !== "user") rows.shift();
  return rows.map((r): ChatMessage =>
    r.role === "user" ? { role: "user", content: r.content }
    : r.role === "tool" ? { role: "tool", toolCallId: r.payload?.toolCallId ?? "", name: r.tool_name ?? "", content: r.content }
    : { role: "assistant", content: r.content, toolCalls: r.payload?.toolCalls });
}

/** One customer message in, one assistant reply out. Everything is persisted. */
export type ChatInput = {
  token: string | null; text: string; ip: string;
  /** Set for messages arriving from an external channel. `phone` is the sender's number as verified by that channel. */
  external?: { channel: "whatsapp" | "sms" | "voice"; id: string; phone?: string };
};

export async function handleChat(business: Business, input: ChatInput): Promise<ChatReply> {
  const ext = input.external;
  // Where to send people when the assistant cannot help.
  const fallback = !ext ? "You can still book with the form on this page."
    : ext.channel === "voice" ? "Please call back later, or book on our website."
    : `You can book online at ${env.appUrl}/b/${business.slug}${business.phone ? ` or call ${business.phone}` : ""}.`;
  const text = input.text.trim();
  if (!text) throw new AppError("invalid", "Please type a message.", 400);
  if (text.length > 1000) throw new AppError("invalid", "That message is too long. Please keep it under 1000 characters.", 400);

  // The kill switch: when staff pause the assistant, no model is called and no tool runs.
  if (!business.ai_enabled) {
    return { token: input.token ?? "", reply: `The booking assistant is paused at the moment. ${fallback}`, escalated: false, degraded: true };
  }
  await rateLimit(`chat:ip:${input.ip}`, 40, 300);
  const { conv, token } = ext ? await loadExternalConversation(business.id, ext.channel, ext.id) : await loadConversation(business.id, input.token);
  await rateLimit(`chat:conv:${conv.id}`, 20, 60);
  if (conv.turn >= MAX_TURNS) {
    return { token, reply: `This conversation has become very long. ${fallback}`, escalated: conv.status === "escalated", degraded: true };
  }

  conv.turn += 1;
  await q("UPDATE conversations SET turn = $2, updated_at = now() WHERE id = $1", [conv.id, conv.turn]);
  await save(conv.id, "user", text);

  const ctx = await loadContext(business.id);
  const [agent, faqs] = await Promise.all([getAgent(business.id), getFaqs(business.id)]);
  const system = buildSystemPrompt(ctx, agent, faqs, new Date(), ext?.phone, ext?.channel);
  const context = buildLocalContext(ctx, agent, faqs, new Date(), ext?.phone);
  const tc: ToolContext = { businessId: business.id, ip: input.ip, conversation: conv, knownPhone: ext?.phone };
  const messages = await history(conv.id);

  let ticket: ToolOutcome["ticket"];
  let escalated = conv.status === "escalated";
  let tokensIn = 0, tokensOut = 0;
  let providerName = "";

  try {
    const provider = await aiProvider();
    providerName = provider.name;
    for (let round = 0; round < MAX_TOOL_ROUNDS; round++) {
      const res = await provider.chat({ system, messages, tools: TOOL_DEFS, context });
      tokensIn += res.usage?.in ?? 0;
      tokensOut += res.usage?.out ?? 0;

      if (!res.toolCalls.length) {
        const reply = res.text.trim() || "Sorry, I didn't catch that. Could you say it another way?";
        await save(conv.id, "assistant", reply);
        await finish(conv.id, business.id, providerName, tokensIn, tokensOut);
        return { token, reply, ticket, escalated, degraded: false };
      }

      const calls = res.toolCalls.slice(0, 4);
      messages.push({ role: "assistant", content: res.text, toolCalls: calls });
      await save(conv.id, "assistant", res.text, null, { toolCalls: calls });
      for (const c of calls) {
        let outcome: ToolOutcome;
        try {
          outcome = await executeTool(tc, c);
        } catch (e) {
          log("error", "tool failed", { tool: c.name, conversation: conv.id, error: (e as Error).message });
          outcome = { result: { status: "error", message: "That action failed because of an internal error. Nothing was changed." } };
        }
        if (outcome.ticket) ticket = outcome.ticket;
        if (outcome.escalated) escalated = true;
        const content = JSON.stringify(outcome.result);
        messages.push({ role: "tool", toolCallId: c.id, name: c.name, content });
        await save(conv.id, "tool", content, c.name, { toolCallId: c.id });
      }
    }
    // The model kept calling tools without answering.
    const reply = `Sorry, I'm having trouble completing that. ${fallback}`;
    await save(conv.id, "assistant", reply);
    await finish(conv.id, business.id, providerName, tokensIn, tokensOut);
    return { token, reply, ticket, escalated, degraded: false };
  } catch (e) {
    if (e instanceof AppError) throw e;
    // Provider down, timed out or misconfigured: say so honestly. Any booking already made in this
    // turn is real and its ticket is still returned.
    log("error", "ai provider failed", { business: business.id, conversation: conv.id, provider: providerName, error: (e as Error).message.slice(0, 300) });
    await save(conv.id, "system", `Assistant unavailable: ${(e as Error).message.slice(0, 300)}`);
    await finish(conv.id, business.id, providerName, tokensIn, tokensOut);
    const reply = ticket
      ? `Your reservation is confirmed (reference ${ticket.reference}). The assistant then ran into a problem, but your booking is safe — here is your ticket: ${ticket.url}`
      : `Sorry — the booking assistant is unavailable right now. ${fallback}`;
    return { token, reply, ticket, escalated, degraded: true };
  }
}

async function finish(conversationId: string, businessId: string, provider: string, tin: number, tout: number) {
  await q("UPDATE conversations SET provider = $2, tokens_in = tokens_in + $3, tokens_out = tokens_out + $4, updated_at = now() WHERE id = $1", [conversationId, provider, tin, tout]);
  await publish({ businessId, type: "conversation.updated", id: conversationId });
}

/** Messages the customer may see again when they reopen the page (no tool internals). */
export async function publicTranscript(businessId: string, token: string) {
  if (!token || token.length > 100) return [];
  return q<{ role: string; content: string }>(
    `SELECT m.role, m.content FROM messages m JOIN conversations c ON c.id = m.conversation_id
      WHERE c.token_hash = $1 AND c.business_id = $2 AND m.role IN ('user','assistant') AND m.content <> '' ORDER BY m.id LIMIT 200`,
    [sha256(token), businessId]);
}
