import { z } from "zod";
import { handleChat, publicTranscript } from "@/lib/ai/agent";
import { getPublicBusiness } from "@/lib/business";
import { notFound } from "@/lib/errors";
import { body, clientIp, route } from "@/lib/http";
import { rateLimit } from "@/lib/ratelimit";

type P = { slug: string };

export const POST = route<P>(async (req, { slug }) => {
  const business = await getPublicBusiness(slug);
  if (!business) throw notFound("Business not found");
  const input = await body(req, z.object({ message: z.string().max(2000), token: z.string().max(100).nullable().optional() }), 8000);
  const r = await handleChat(business, { token: input.token ?? null, text: input.message, ip: clientIp(req) });
  // The ticket URL is returned relative so it works on whatever host the page is served from.
  const ticket = r.ticket ? { ...r.ticket, url: new URL(r.ticket.url).pathname } : undefined;
  return { ...r, ticket };
});

// Restore the visitor's own conversation after a page reload.
export const GET = route<P>(async (req, { slug }) => {
  await rateLimit(`chat:get:${clientIp(req)}`, 60, 60);
  const business = await getPublicBusiness(slug);
  if (!business) throw notFound("Business not found");
  const token = req.headers.get("x-conversation-token") ?? "";
  return { messages: await publicTranscript(business.id, token) };
});
