import { DateTime } from "luxon";
import { z } from "zod";
import { one, q } from "../db";
import { AppError } from "../errors";
import { sha256, ticketToken } from "../crypto";
import { env } from "../env";
import { rateLimit } from "../ratelimit";
import { publish } from "../realtime";
import {
  findAlternatives, getDayAvailability, loadContext, pickService, reasonText, checkSlot, loadBusy, type BookingContext,
} from "../booking/availability";
import {
  cancelReservation, cleanCustomer, createReservation, customerCanChange, findReservationByReferenceAndContact,
  getReservation, rescheduleReservation, type ReservationRow,
} from "../booking/reservations";
import type { ToolCall, ToolDef } from "./provider";

// ----------------------------------------------------------------------------
// Tool definitions: the complete list of things the assistant is able to do.
// It has no other access to the database, the network or the server.
// ----------------------------------------------------------------------------
const date = { type: "string", description: "Calendar date in the business's time zone, YYYY-MM-DD" };
const time = { type: "string", description: "24-hour local time, HH:MM" };
const reference = { type: "string", description: "The 6-character booking reference" };
const contact = { type: "string", description: "The email address or phone number the booking was made with. Needed unless the booking was made in this conversation." };

export const TOOL_DEFS: ToolDef[] = [
  {
    name: "check_availability",
    description: "Look up real availability. Without `time` it returns every free time that day. With `time` it says whether that exact time is free and, if not, returns real alternatives. Always call this before telling a customer a time is or is not available.",
    parameters: { type: "object", properties: { date, party_size: { type: "integer", minimum: 1 }, time }, required: ["date", "party_size"] },
  },
  {
    name: "create_reservation",
    description: "Book a reservation. The first call returns status \"needs_confirmation\" with a summary: read that summary to the customer and ask them to confirm. Only after the customer clearly says yes in a later message, call again with exactly the same details to actually book.",
    parameters: {
      type: "object",
      properties: {
        date, time, party_size: { type: "integer", minimum: 1 },
        customer_name: { type: "string" },
        email: { type: "string", description: "Customer email (email or phone is required)" },
        phone: { type: "string", description: "Customer phone (email or phone is required)" },
        notes: { type: "string", description: "Special requests, in the customer's words" },
      },
      required: ["date", "time", "party_size", "customer_name"],
    },
  },
  { name: "get_reservation", description: "Look up an existing reservation.", parameters: { type: "object", properties: { reference, contact }, required: ["reference"] } },
  {
    name: "reschedule_reservation",
    description: "Move an existing reservation to a new date/time (and optionally a new party size). First call returns \"needs_confirmation\"; call again with the same details after the customer confirms.",
    parameters: { type: "object", properties: { reference, contact, new_date: date, new_time: time, party_size: { type: "integer", minimum: 1 } }, required: ["reference", "new_date", "new_time"] },
  },
  {
    name: "cancel_reservation",
    description: "Cancel an existing reservation. First call returns \"needs_confirmation\"; call again with the same details after the customer confirms.",
    parameters: { type: "object", properties: { reference, contact }, required: ["reference"] },
  },
  { name: "generate_ticket", description: "Get the link to the digital ticket (with QR code) for a reservation.", parameters: { type: "object", properties: { reference, contact }, required: ["reference"] } },
  {
    name: "escalate_to_human",
    description: "Hand the conversation to staff. Use when the customer asks for a person, is upset, has a request you cannot handle with your tools, or needs something the business information does not cover.",
    parameters: {
      type: "object",
      properties: {
        reason: { type: "string", description: "Why a human is needed" },
        summary: { type: "string", description: "Short summary of what the customer wants and what was already tried" },
        customer_name: { type: "string" },
        customer_contact: { type: "string", description: "How staff can reach the customer, if they gave it" },
      },
      required: ["reason", "summary"],
    },
  },
];

// ----------------------------------------------------------------------------
// Argument validation. Model output is untrusted input like any other.
// ----------------------------------------------------------------------------
const zDate = z.string().regex(/^\d{4}-\d{2}-\d{2}$/, "date must be YYYY-MM-DD");
const zTime = z.string().regex(/^([01]\d|2[0-3]):[0-5]\d$/, "time must be HH:MM (24-hour)");
const zParty = z.coerce.number().int().min(1).max(500);
const zRef = z.string().trim().min(4).max(12);
const zOpt = (max: number) => z.string().trim().max(max).optional().nullable();

const SCHEMAS = {
  check_availability: z.object({ date: zDate, party_size: zParty, time: zTime.optional().nullable() }),
  create_reservation: z.object({ date: zDate, time: zTime, party_size: zParty, customer_name: z.string().trim().min(2).max(80), email: zOpt(160), phone: zOpt(30), notes: zOpt(500) }),
  get_reservation: z.object({ reference: zRef, contact: zOpt(160) }),
  reschedule_reservation: z.object({ reference: zRef, contact: zOpt(160), new_date: zDate, new_time: zTime, party_size: zParty.optional().nullable() }),
  cancel_reservation: z.object({ reference: zRef, contact: zOpt(160) }),
  generate_ticket: z.object({ reference: zRef, contact: zOpt(160) }),
  escalate_to_human: z.object({ reason: z.string().trim().min(1).max(300), summary: z.string().trim().min(1).max(1500), customer_name: zOpt(80), customer_contact: zOpt(160) }),
};

type Pending = { type: "create" | "cancel" | "reschedule"; fingerprint: string; turn: number };

export type ToolContext = {
  businessId: string;           // fixed by the server from the page the customer is on — never taken from the model
  ip: string;
  conversation: { id: string; turn: number; pending_action: Pending | null; reservation_id: string | null };
  /** The customer's own number, verified by the channel they are writing from (WhatsApp). Never supplied by the model. */
  knownPhone?: string;
};

export type ToolOutcome = {
  result: Record<string, unknown>;
  ticket?: { url: string; reference: string; when: string; party_size: number; name: string };
  escalated?: boolean;
  outcome?: "booked" | "cancelled" | "rescheduled" | "escalated";
};

const toStart = (ctx: BookingContext, d: string, t: string) => DateTime.fromISO(`${d}T${t}`, { zone: ctx.business.timezone });
const label = (dt: DateTime) => dt.toFormat("cccc d LLLL yyyy 'at' HH:mm");

function describe(r: ReservationRow, ctx: BookingContext) {
  const dt = DateTime.fromJSDate(r.starts_at, { zone: ctx.business.timezone });
  return { reference: r.reference, reservation_status: r.status, date: dt.toISODate(), time: dt.toFormat("HH:mm"), when: label(dt), party_size: r.party_size, service: r.service_name, name: r.customer_name };
}

async function setPending(tc: ToolContext, p: Pending | null) {
  tc.conversation.pending_action = p;
  await q("UPDATE conversations SET pending_action = $2 WHERE id = $1 AND business_id = $3", [tc.conversation.id, p ? JSON.stringify(p) : null, tc.businessId]);
}

/**
 * Two-step confirmation enforced by the server, not by the prompt: the first call records what was
 * proposed and returns false. A second call counts only if it carries identical details AND arrives
 * in a later customer turn — i.e. the customer has seen the summary and replied.
 */
async function confirmed(tc: ToolContext, type: Pending["type"], details: unknown): Promise<boolean> {
  const fingerprint = sha256(JSON.stringify(details));
  const p = tc.conversation.pending_action;
  if (p && p.type === type && p.fingerprint === fingerprint && p.turn < tc.conversation.turn) return true;
  if (!(p && p.type === type && p.fingerprint === fingerprint)) await setPending(tc, { type, fingerprint, turn: tc.conversation.turn });
  return false;
}

/** A customer may touch a booking made in this conversation, or one they can prove is theirs. */
async function authorize(tc: ToolContext, ref: string, contactValue?: string | null): Promise<ReservationRow | null> {
  const clean = ref.toUpperCase().replace(/[^A-Z0-9]/g, "");
  if (tc.conversation.reservation_id) {
    const own = await getReservation(tc.businessId, tc.conversation.reservation_id);
    if (own && own.reference === clean) return own;
  }
  // On WhatsApp the sender's number is verified by the channel, so it counts as their contact detail.
  if (tc.knownPhone) {
    await rateLimit(`lookup:conv:${tc.conversation.id}`, 6, 3600);
    const byPhone = await findReservationByReferenceAndContact(tc.businessId, clean, tc.knownPhone);
    if (byPhone) return byPhone;
  }
  if (!contactValue) return null;
  // Guessing references is slow by design.
  await rateLimit(`lookup:conv:${tc.conversation.id}`, 6, 3600);
  await rateLimit(`lookup:ip:${tc.ip}`, 20, 3600);
  return findReservationByReferenceAndContact(tc.businessId, clean, contactValue);
}

const NOT_FOUND = {
  status: "not_found",
  message: "No reservation matches that reference and contact detail. Ask the customer to check the 6-character reference and give the email or phone number used for the booking.",
};

// ----------------------------------------------------------------------------
// Execution
// ----------------------------------------------------------------------------
export async function executeTool(tc: ToolContext, call: ToolCall): Promise<ToolOutcome> {
  const schema = SCHEMAS[call.name as keyof typeof SCHEMAS];
  if (!schema) return { result: { status: "error", message: `Unknown tool "${String(call.name).slice(0, 40)}".` } };
  const parsed = schema.safeParse(call.arguments);
  if (!parsed.success) {
    const i = parsed.error.issues[0];
    return { result: { status: "invalid_arguments", message: `${i.path.join(".")}: ${i.message}` } };
  }
  try {
    return await run(tc, call.name as keyof typeof SCHEMAS, parsed.data as never);
  } catch (e) {
    if (e instanceof AppError) return { result: { status: e.code, message: e.message, ...(e.data ?? {}) } };
    throw e;
  }
}

async function run(tc: ToolContext, name: keyof typeof SCHEMAS, a: Record<string, never>): Promise<ToolOutcome> {
  const ctx = await loadContext(tc.businessId);
  const tz = ctx.business.timezone;

  switch (name) {
    case "check_availability": {
      const args = a as unknown as z.infer<typeof SCHEMAS.check_availability>;
      if (!ctx.business.online_booking_enabled) return { result: { status: "booking_disabled", message: "Online reservations are paused. Give the customer the business's contact details." } };
      const day = await getDayAvailability(tc.businessId, { date: args.date, partySize: args.party_size }, undefined, ctx);
      const weekday = DateTime.fromISO(args.date, { zone: tz }).toFormat("cccc d LLLL yyyy");
      const free = day.slots.filter((s) => s.available).map((s) => s.time);
      if (!args.time) {
        if (free.length) return { result: { status: "ok", date: args.date, day: weekday, party_size: args.party_size, free_times: free } };
        const alternatives = await findAlternatives(tc.businessId, { date: args.date, partySize: args.party_size, limit: 4 });
        return { result: { status: "none_available", date: args.date, day: weekday, reason: day.closedReason ?? "Fully booked for that party size.", alternatives: alternatives.map(alt(tz)) } };
      }
      const slot = day.slots.find((s) => s.time === args.time);
      if (slot?.available) return { result: { status: "available", date: args.date, day: weekday, time: args.time, party_size: args.party_size } };
      const service = pickService(ctx)!;
      const reason = slot ? reasonText(slot.reason, ctx)
        : day.open ? reasonText(checkSlot(ctx, service, toStart(ctx, args.date, args.time).toJSDate(), args.party_size, []).reason, ctx) || "That time is not bookable."
        : day.closedReason ?? "Closed that day.";
      const alternatives = await findAlternatives(tc.businessId, { date: args.date, time: args.time, partySize: args.party_size, limit: 4 });
      return { result: { status: "unavailable", date: args.date, day: weekday, time: args.time, reason, alternatives: alternatives.map(alt(tz)) } };
    }

    case "create_reservation": {
      const args = a as unknown as z.infer<typeof SCHEMAS.create_reservation>;
      const start = toStart(ctx, args.date, args.time);
      if (!start.isValid) return { result: { status: "invalid_arguments", message: "That date or time does not exist." } };
      const customer = cleanCustomer({ name: args.customer_name, email: args.email || null, phone: args.phone || tc.knownPhone || null });
      const details = { d: args.date, t: args.time, p: args.party_size, n: customer.name.toLowerCase(), e: customer.email, ph: customer.phone?.replace(/\D/g, "") ?? null };

      if (!(await confirmed(tc, "create", details))) {
        // Check now, so the customer is never asked to confirm something that cannot be booked.
        if (!ctx.business.online_booking_enabled) return { result: { status: "booking_disabled", message: "Online reservations are paused." } };
        const service = pickService(ctx);
        if (!service) return { result: { status: "error", message: "No bookable service is configured." } };
        const busy = await loadBusy(tc.businessId, start.minus({ days: 1 }).toJSDate(), start.plus({ days: 2 }).toJSDate());
        const check = checkSlot(ctx, service, start.toJSDate(), args.party_size, busy);
        if (!check.ok) {
          await setPending(tc, null);
          const alternatives = await findAlternatives(tc.businessId, { date: args.date, time: args.time, partySize: args.party_size, limit: 4 });
          return { result: { status: "unavailable", reason: reasonText(check.reason, ctx), alternatives: alternatives.map(alt(tz)) } };
        }
        return {
          result: {
            status: "needs_confirmation",
            summary: { business: ctx.business.name, when: label(start), party_size: args.party_size, name: customer.name, email: customer.email, phone: customer.phone, notes: args.notes || null },
            instruction: "Nothing is booked yet. Read this summary to the customer and ask them to confirm. After they clearly say yes, call create_reservation again with exactly the same details.",
          },
        };
      }

      const made = await createReservation({
        businessId: tc.businessId, startsAt: start.toUTC().toISO()!, partySize: args.party_size, customer,
        notes: args.notes ?? "", source: "ai", actor: { type: "ai" }, conversationId: tc.conversation.id,
        idempotencyKey: `conv:${tc.conversation.id}:${sha256(JSON.stringify(details)).slice(0, 24)}`,
      });
      await setPending(tc, null);
      tc.conversation.reservation_id = made.reservation.id;
      const d = describe(made.reservation, ctx);
      const url = `${env.appUrl}/t/${made.ticketToken}`;
      return {
        result: { status: "confirmed", ...d, ticket_url: url, instruction: "The reservation is booked. Give the customer the reference and the ticket link." },
        ticket: { url, reference: d.reference, when: d.when, party_size: d.party_size, name: d.name },
        outcome: "booked",
      };
    }

    case "get_reservation": {
      const args = a as unknown as z.infer<typeof SCHEMAS.get_reservation>;
      const r = await authorize(tc, args.reference, args.contact);
      if (!r) return { result: NOT_FOUND };
      const can = customerCanChange(r, ctx.policies);
      return { result: { status: "found", ...describe(r, ctx), can_change_or_cancel: can.allowed, ...(can.allowed ? {} : { why_not: can.reason }) } };
    }

    case "generate_ticket": {
      const args = a as unknown as z.infer<typeof SCHEMAS.generate_ticket>;
      const r = await authorize(tc, args.reference, args.contact);
      if (!r || !r.ticket_id) return { result: NOT_FOUND };
      if (r.status === "cancelled") return { result: { status: "cancelled", message: "This reservation was cancelled, so its ticket is no longer valid." } };
      const d = describe(r, ctx);
      const url = `${env.appUrl}/t/${ticketToken(r.ticket_id)}`;
      return { result: { status: "ok", ...d, ticket_url: url }, ticket: { url, reference: d.reference, when: d.when, party_size: d.party_size, name: d.name } };
    }

    case "cancel_reservation": {
      const args = a as unknown as z.infer<typeof SCHEMAS.cancel_reservation>;
      const r = await authorize(tc, args.reference, args.contact);
      if (!r) return { result: NOT_FOUND };
      if (r.status === "cancelled") return { result: { status: "already_cancelled", ...describe(r, ctx) } };
      const can = customerCanChange(r, ctx.policies);
      if (!can.allowed) return { result: { status: "change_not_allowed", message: can.reason } };
      if (!(await confirmed(tc, "cancel", { id: r.id }))) {
        return { result: { status: "needs_confirmation", summary: describe(r, ctx), instruction: "Nothing is cancelled yet. Ask the customer to confirm they want to cancel this reservation, then call cancel_reservation again with the same details." } };
      }
      const done = await cancelReservation(tc.businessId, r.id, { type: "ai" }, { enforceCustomerRules: true });
      await setPending(tc, null);
      await q("UPDATE conversations SET outcome = 'cancelled' WHERE id = $1", [tc.conversation.id]);
      return { result: { status: "cancelled", ...describe(done, ctx) }, outcome: "cancelled" };
    }

    case "reschedule_reservation": {
      const args = a as unknown as z.infer<typeof SCHEMAS.reschedule_reservation>;
      const r = await authorize(tc, args.reference, args.contact);
      if (!r) return { result: NOT_FOUND };
      const can = customerCanChange(r, ctx.policies);
      if (!can.allowed) return { result: { status: "change_not_allowed", message: can.reason } };
      const start = toStart(ctx, args.new_date, args.new_time);
      if (!start.isValid) return { result: { status: "invalid_arguments", message: "That date or time does not exist." } };
      const party = args.party_size ?? r.party_size;
      if (!(await confirmed(tc, "reschedule", { id: r.id, d: args.new_date, t: args.new_time, p: party }))) {
        const service = ctx.services.find((s) => s.id === r.service_id)!;
        const busy = await loadBusy(tc.businessId, start.minus({ days: 1 }).toJSDate(), start.plus({ days: 2 }).toJSDate());
        const check = checkSlot(ctx, service, start.toJSDate(), party, busy, { excludeReservationId: r.id });
        if (!check.ok) {
          await setPending(tc, null);
          const alternatives = await findAlternatives(tc.businessId, { date: args.new_date, time: args.new_time, partySize: party, limit: 4, excludeReservationId: r.id });
          return { result: { status: "unavailable", reason: reasonText(check.reason, ctx), alternatives: alternatives.map(alt(tz)) } };
        }
        return { result: { status: "needs_confirmation", summary: { reference: r.reference, from: describe(r, ctx).when, to: label(start), party_size: party }, instruction: "Nothing is changed yet. Ask the customer to confirm the new time, then call reschedule_reservation again with the same details." } };
      }
      const moved = await rescheduleReservation(tc.businessId, r.id, { startsAt: start.toUTC().toISO()!, partySize: party }, { type: "ai" }, { enforceCustomerRules: true });
      await setPending(tc, null);
      await q("UPDATE conversations SET outcome = 'rescheduled' WHERE id = $1", [tc.conversation.id]);
      const d = describe(moved, ctx);
      const url = moved.ticket_id ? `${env.appUrl}/t/${ticketToken(moved.ticket_id)}` : "";
      return { result: { status: "rescheduled", ...d, ticket_url: url }, outcome: "rescheduled", ...(url ? { ticket: { url, reference: d.reference, when: d.when, party_size: d.party_size, name: d.name } } : {}) };
    }

    case "escalate_to_human": {
      const args = a as unknown as z.infer<typeof SCHEMAS.escalate_to_human>;
      const agent = await one<{ handoff_contact: string }>("SELECT handoff_contact FROM agent_configs WHERE business_id = $1", [tc.businessId]);
      await q(
        "UPDATE conversations SET status = 'escalated', outcome = coalesce(outcome, 'escalated'), escalation = $2, updated_at = now() WHERE id = $1 AND business_id = $3",
        [tc.conversation.id, JSON.stringify({ reason: args.reason, summary: args.summary, customer_name: args.customer_name ?? null, customer_contact: args.customer_contact ?? null, at: new Date().toISOString() }), tc.businessId],
      );
      await publish({ businessId: tc.businessId, type: "conversation.updated", id: tc.conversation.id });
      const reach = [agent?.handoff_contact, ctx.business.phone, ctx.business.contact_email].filter(Boolean)[0] ?? null;
      return {
        result: {
          status: "escalated",
          contact: reach,
          has_customer_contact: Boolean(args.customer_contact),
          instruction: "Staff have been notified and can see this conversation. Tell the customer that, share the contact detail if there is one, and if you do not have a way to reach the customer, ask for their name and phone or email. Do not promise a response time.",
        },
        escalated: true,
        outcome: "escalated",
      };
    }
  }
}

const alt = (tz: string) => (a: { date: string; time: string }) => ({
  date: a.date, time: a.time, day: DateTime.fromISO(a.date, { zone: tz }).toFormat("cccc d LLLL"),
});
