import { DateTime, IANAZone } from "luxon";

export const isValidZone = (tz: string) => IANAZone.isValidZone(tz);
export const isIsoDate = (s: string) => /^\d{4}-\d{2}-\d{2}$/.test(s) && DateTime.fromISO(s).isValid;

/** Start of a business-local calendar day. */
export function dayStart(date: string, tz: string): DateTime {
  return DateTime.fromISO(date, { zone: tz }).startOf("day");
}

export function todayIn(tz: string, now: Date = new Date()): string {
  return DateTime.fromJSDate(now, { zone: tz }).toISODate()!;
}

export function localDate(d: Date, tz: string): string {
  return DateTime.fromJSDate(d, { zone: tz }).toISODate()!;
}

export function minutesToLabel(min: number): string {
  const h = Math.floor(min / 60) % 24;
  const m = min % 60;
  return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}`;
}

export function labelToMinutes(s: string): number | null {
  const m = /^(\d{1,2}):(\d{2})$/.exec(s.trim());
  if (!m) return null;
  const h = Number(m[1]), mi = Number(m[2]);
  if (h > 24 || mi > 59 || (h === 24 && mi > 0)) return null;
  return h * 60 + mi;
}

export function fmtTime(d: Date | string, tz: string): string {
  return toDT(d, tz).toFormat("HH:mm");
}
export function fmtDate(d: Date | string, tz: string): string {
  return toDT(d, tz).toFormat("ccc d LLL yyyy");
}
export function fmtDateLong(d: Date | string, tz: string): string {
  return toDT(d, tz).toFormat("cccc d LLLL yyyy");
}
export function fmtDateTime(d: Date | string, tz: string): string {
  return toDT(d, tz).toFormat("ccc d LLL yyyy, HH:mm");
}
/** e.g. "GMT+1" — shown on tickets so the time is unambiguous. */
export function tzLabel(d: Date | string, tz: string): string {
  return toDT(d, tz).toFormat("ZZZZ");
}
function toDT(d: Date | string, tz: string): DateTime {
  return (typeof d === "string" ? DateTime.fromISO(d) : DateTime.fromJSDate(d)).setZone(tz);
}

export const WEEKDAYS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
