// Central, validated access to configuration. Nothing here is ever sent to the browser.

function required(name: string): string {
  const v = process.env[name];
  if (!v) throw new Error(`Missing required environment variable ${name}. See .env.example.`);
  return v;
}

export const env = {
  get databaseUrl() {
    return required("DATABASE_URL");
  },
  get appUrl() {
    return (process.env.APP_URL || "http://localhost:3000").replace(/\/+$/, "");
  },
  get ticketSecret() {
    const s = required("TICKET_SECRET");
    if (process.env.NODE_ENV === "production" && (s.length < 32 || s.startsWith("change-me"))) {
      throw new Error("TICKET_SECRET must be a random value of at least 32 characters in production.");
    }
    return s;
  },
  get aiProvider(): "local" | "openai" {
    return process.env.AI_PROVIDER === "openai" ? "openai" : "local";
  },
  get aiBaseUrl() {
    return (process.env.AI_BASE_URL || "").replace(/\/+$/, "");
  },
  get aiApiKey() {
    return process.env.AI_API_KEY || "";
  },
  get aiModel() {
    return process.env.AI_MODEL || "";
  },
  get aiTimeoutMs() {
    return Number(process.env.AI_TIMEOUT_MS) || 20000;
  },
  get emailProvider(): "log" | "smtp" {
    return process.env.EMAIL_PROVIDER === "smtp" ? "smtp" : "log";
  },
  get emailFrom() {
    return process.env.EMAIL_FROM || "AI Book & Check In <no-reply@example.com>";
  },
  get isProd() {
    return process.env.NODE_ENV === "production";
  },
};
